page('auth/callback/index.html','Confirm your account','Finish confirming or recovering your customer account.',callback,'callback')
# New top-level main tab in the existing compiled React website. Preserve the rest of the bundle.
p=ROOT/'assets/app.js';s=p.read_text();old='{label:"Services",path:"/services"},{label:"Pricing",path:"/pricing"}'
if old in s:s=s.replace(old,'{label:"Services",path:"/services"},{label:"GEO Audit",path:"/geo-audit/"},{label:"Pricing",path:"/pricing"}',1);p.write_text(s)
elif '{label:"GEO Audit",path:"/geo-audit/"}' not in s:raise RuntimeError('Navigation marker changed: manual review required')
# Full navigation avoids React Router treating the new static page as a missing SPA route.
for p in ROOT.glob('*.html'):
 s=p.read_text()
 if '/assets/geo-nav.js' not in s:s=s.replace('</head>','<script defer src="/assets/geo-nav.js"></script></head>')
 p.write_text(s)
(ROOT/'assets/geo-nav.js').write_text('''(()=>{window.addEventListener('click',e=>{if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const a=e.target.closest?.('a[href]');if(!a)return;const u=new URL(a.href,location.href);if(u.origin===location.origin&&u.pathname.replace(/\\/$/,'')==='/geo-audit'){e.preventDefault();e.stopImmediatePropagation();location.assign(u.href);}},true);})();''')
# Crawlable landing URL. Keep draft noindex until launch review.
p=ROOT/'sitemap.xml';s=p.read_text();entry='<url><loc>https://aeogeosearch.com/geo-audit/</loc></url>'
if entry not in s:s=s.replace('</urlset>',entry+'\n</urlset>');p.write_text(s)
print('Built landing page, supplied-style dashboard, account, auth and main-navigation integration.')

